CREATE TABLE games(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE provider_categories(provider TEXT NOT NULL, category_id TEXT NOT NULL, game_id INTEGER NOT NULL REFERENCES games(id), name TEXT NOT NULL, PRIMARY KEY(provider,category_id));
CREATE TABLE sets(id INTEGER PRIMARY KEY, game_id INTEGER NOT NULL REFERENCES games(id), name TEXT NOT NULL, release_date TEXT, last_catalog_sync TEXT);
CREATE TABLE set_mappings(provider TEXT NOT NULL, category_id TEXT NOT NULL, source_set_id TEXT NOT NULL, set_id INTEGER NOT NULL REFERENCES sets(id), PRIMARY KEY(provider,category_id,source_set_id));
CREATE TABLE set_aliases(set_id INTEGER NOT NULL REFERENCES sets(id), alias TEXT NOT NULL, provenance TEXT NOT NULL, PRIMARY KEY(set_id,alias));
CREATE INDEX set_alias_search ON set_aliases(alias,set_id);
CREATE TABLE products(id INTEGER PRIMARY KEY, game_id INTEGER NOT NULL REFERENCES games(id), set_id INTEGER NOT NULL REFERENCES sets(id), name TEXT NOT NULL, collector_number TEXT, raw_collector_number TEXT, tcgplayer_product_id TEXT NOT NULL UNIQUE, language TEXT, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX product_identity ON products(game_id,set_id,collector_number);
CREATE INDEX product_name ON products(name COLLATE NOCASE,id);
CREATE TABLE documents(id INTEGER PRIMARY KEY, url TEXT NOT NULL, content_hash TEXT NOT NULL, original_source_hash TEXT NOT NULL, payload BLOB NOT NULL, payload_kind TEXT NOT NULL CHECK(payload_kind IN ('original','excerpt')), retrieved_at TEXT NOT NULL, last_checked_at TEXT NOT NULL, UNIQUE(url,content_hash));
CREATE TABLE product_sources(provider TEXT NOT NULL, source_product_id TEXT NOT NULL, product_id INTEGER NOT NULL REFERENCES products(id), document_id INTEGER NOT NULL REFERENCES documents(id), locator TEXT NOT NULL, PRIMARY KEY(provider,source_product_id));
CREATE TABLE skus(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), provider TEXT NOT NULL, provider_sku_id TEXT NOT NULL, condition TEXT CHECK(condition IN ('NM','LP','MP','HP','DMG') OR condition IS NULL), language TEXT, edition TEXT, finish TEXT, graded INTEGER CHECK(graded IN (0,1) OR graded IS NULL), raw_variant_json TEXT NOT NULL, completeness_json TEXT NOT NULL, provenance_json TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(provider,provider_sku_id));
CREATE INDEX sku_identity ON skus(product_id,condition,language,edition,finish,graded,active);
CREATE TABLE observations(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), sku_id INTEGER REFERENCES skus(id), provider TEXT NOT NULL, market_price TEXT CHECK(market_price IS NULL OR (typeof(market_price)='text' AND CAST(market_price AS REAL)>0)), currency TEXT, price_type TEXT NOT NULL CHECK(price_type IN ('sku_market_reference','generic_market_reference')), source_updated_at TEXT, retrieved_at TEXT NOT NULL, source_url TEXT NOT NULL, document_id INTEGER NOT NULL REFERENCES documents(id), locator TEXT NOT NULL, evidence_json TEXT NOT NULL, warnings_json TEXT NOT NULL, missing_json TEXT NOT NULL, fingerprint TEXT NOT NULL UNIQUE, CHECK((sku_id IS NULL AND price_type='generic_market_reference') OR (sku_id IS NOT NULL AND price_type='sku_market_reference')));
CREATE INDEX observation_latest ON observations(sku_id,provider,retrieved_at DESC,id DESC);
CREATE INDEX observation_generic ON observations(product_id,price_type,retrieved_at DESC);
CREATE TRIGGER observation_product_guard BEFORE INSERT ON observations WHEN NEW.sku_id IS NOT NULL AND (SELECT product_id FROM skus WHERE id=NEW.sku_id)!=NEW.product_id BEGIN SELECT RAISE(ABORT,'SKU/product mismatch'); END;
CREATE TABLE sync_state(provider TEXT NOT NULL, category_id TEXT NOT NULL, source_set_id TEXT NOT NULL, last_attempt_at TEXT, last_success_at TEXT, source_marker TEXT, request_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, errors_json TEXT NOT NULL DEFAULT '[]', retry_after TEXT, refresh_hours INTEGER NOT NULL DEFAULT 24, priority INTEGER NOT NULL DEFAULT 0, event_note TEXT, PRIMARY KEY(provider,category_id,source_set_id));
CREATE TABLE endpoints(url TEXT PRIMARY KEY, document_id INTEGER REFERENCES documents(id), last_attempt_at TEXT, last_success_at TEXT, etag TEXT, last_modified TEXT, status TEXT, error TEXT, next_attempt_at TEXT, request_count INTEGER NOT NULL DEFAULT 0);
PRAGMA user_version=1;
